<?php /** @var array<string,mixed> $upi */ /** @var array<string,mixed> $api */ /** @var array<string,mixed> $upiStatus */ /** @var array<string,mixed> $apiStatus */ /** @var array<string,string> $networks */ /** @var array<string,string> $authMethods */ /** @var ?array<string,mixed> $check */ /** @var bool $profileOk */
$u = $upi['config']; $a = $api['config']; $uv = static fn (string $k) => old($k, (string) ($u[$k] ?? '')); $av = static fn (string $k) => old($k, (string) ($a[$k] ?? ''));
$selNet = (array) ($a['networks'] ?? ['VISA', 'MASTERCARD']); $selAuth = (array) ($a['auth_methods'] ?? ['PAN_ONLY', 'CRYPTOGRAM_3DS']); ?>
<div class="page-head"><div><p class="eyebrow">Administration</p><h1>Payments (Google Pay)</h1></div><a class="btn btn-ghost" href="/admin/business">Business details</a></div>
<div class="alert alert-ok" role="status"><p><strong>Read this first.</strong> Google Pay is not a payment gateway on its own. There are two ways to take Google Pay money, and each has its own section below. Nothing on this page moves money by itself, and no payment is ever shown as received until a person has checked it.</p></div>
<?php if (!$profileOk) : ?><div class="alert alert-error" role="status"><p>Business details are not set yet: <a href="/admin/business">set them</a> before issuing invoices.</p></div><?php endif; ?>

<div class="panel"><h2>1. Google Pay by UPI <span class="badge badge-sys-<?= $upiStatus['state'] === 'ready' ? 'ok' : 'warn' ?>"><?= e($upiStatus['label']) ?></span></h2>
    <p class="muted">Clients tap <strong>Pay with Google Pay</strong> on an invoice. The link opens Google Pay (or any UPI app) with your UPI ID, the amount and the invoice number filled in. Money goes straight to your bank account; there are no gateway fees. UPI does not report back to this system, so the client then enters the transaction (UTR) number and <strong>you verify it against your bank statement</strong> (Client payments) before the invoice shows as paid. Works today; needs no processor.</p>
    <?php foreach ($upiStatus['notes'] as $n) : ?><p><?= e($n) ?></p><?php endforeach; ?>
    <form method="post" action="/admin/payments" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="save_upi">
        <div class="field"><label for="vpa">Your UPI ID (as shown in Google Pay)</label><input id="vpa" name="upi_id" required maxlength="320" autocomplete="off" placeholder="yourname@okhdfcbank" value="<?= e($uv('upi_id')) ?>"></div>
        <div class="field"><label for="pn">Name shown to the payer</label><input id="pn" name="payee_name" required maxlength="99" value="<?= e($uv('payee_name')) ?>"></div>
        <div class="field"><label for="mc">Merchant category code (optional, 4 digits)</label><input id="mc" name="merchant_code" maxlength="4" inputmode="numeric" value="<?= e($uv('merchant_code')) ?>"></div>
        <div class="field"><label class="check"><input type="checkbox" name="enabled" value="1"<?= (old('enabled', $upi['enabled'] ? '1' : '0') === '1') ? ' checked' : '' ?>> Show the Pay with Google Pay button on invoices</label></div>
        <div class="field"><label for="pw1">Your password</label><input id="pw1" name="confirm_password" type="password" required autocomplete="current-password"></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Save</button></div></form>
    <?php if ($u !== []) : ?><form method="post" action="/admin/payments" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="check_upi"><button class="btn btn-ghost btn-sm" type="submit">Check these settings</button></form><?php endif; ?>
    <?php if ($check) : ?><div class="note"><?php foreach ($check['messages'] as $m) : ?><p><?= e($m) ?></p><?php endforeach; ?><?php if ($check['sample']) : ?><p class="muted">Example link a client would get for ₹100: <code class="prewrap"><?= e($check['sample']) ?></code></p><?php endif; ?></div><?php endif; ?>
    <?php if ($upi['updated_at']) : ?><p class="muted">Last saved <?= e(local_time($upi['updated_at'])) ?><?= $upi['updated_by'] ? ' by ' . e($upi['updated_by']) : '' ?>.</p><?php endif; ?>
    <p class="muted">Tip: a personal UPI ID can be limited by Google Pay for business payments. A Google Pay for Business / merchant UPI ID is better. Make one real ₹1 payment to yourself to prove the ID works.</p></div>

<div class="panel"><h2>2. Google Pay API (cards and wallet tokens through a payment processor) <span class="badge badge-sys-warn"><?= e($apiStatus['label']) ?></span></h2>
    <p class="muted">For paying with cards saved in Google Pay. Google Pay encrypts the card and hands it to a <strong>payment processor</strong> (for example Razorpay, PayU, Cashfree or Stripe) that actually charges it. You need: (1) a Google Pay &amp; Wallet Console business profile and merchant ID (Google reviews your website before PRODUCTION is allowed), and (2) an account with a processor that supports Google Pay, with its merchant ID and API keys. Enter them here so the connection can be completed.</p>
    <?php foreach ($apiStatus['notes'] as $n) : ?><div class="alert alert-error" role="status"><p><?= e($n) ?></p></div><?php endforeach; ?>
    <form method="post" action="/admin/payments" class="form-grid" autocomplete="off"><?= csrf_field() ?><input type="hidden" name="action" value="save_api">
        <div class="field"><label for="env">Environment</label><select id="env" name="environment"><?php foreach (['TEST' => 'TEST (no real money)', 'PRODUCTION' => 'PRODUCTION (after Google approves you)'] as $c => $l) : ?><option value="<?= e($c) ?>"<?= ($av('environment') ?: 'TEST') === $c ? ' selected' : '' ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
        <div class="field"><label for="gmid">Google Pay merchant ID (from the Google Pay &amp; Wallet Console)</label><input id="gmid" name="merchant_id" maxlength="32" value="<?= e($av('merchant_id')) ?>"><p class="hint">Required for PRODUCTION. Optional in TEST.</p></div>
        <div class="field"><label for="gmn">Merchant name shown in Google Pay</label><input id="gmn" name="merchant_name" required maxlength="100" value="<?= e($av('merchant_name')) ?>"></div>
        <div class="field"><label for="gor">Your website address (https, no path)</label><input id="gor" name="merchant_origin" maxlength="190" placeholder="https://pay.example.com" value="<?= e($av('merchant_origin')) ?>"></div>
        <div class="field"><label for="gp">Payment processor identifier</label><input id="gp" name="processor" required maxlength="41" placeholder="razorpay" value="<?= e($av('processor')) ?>"><p class="hint">The "gateway" value your processor documents for Google Pay.</p></div>
        <div class="field"><label for="gpm">Your merchant ID at the processor ("gatewayMerchantId")</label><input id="gpm" name="processor_merchant_id" required maxlength="100" value="<?= e($av('processor_merchant_id')) ?>"></div>
        <div class="field"><label for="gki">Processor API key ID</label><input id="gki" name="processor_key_id" maxlength="120" value="<?= e($av('processor_key_id')) ?>"></div>
        <div class="field"><label for="gks">Processor API secret <?= isset($api['secrets_set']['processor_key_secret']) ? '<span class="badge badge-active">saved ' . e($api['secrets_set']['processor_key_secret']) . '</span>' : '' ?></label><input id="gks" name="processor_key_secret" type="password" maxlength="200" autocomplete="new-password" placeholder="<?= isset($api['secrets_set']['processor_key_secret']) ? 'leave empty to keep the saved secret' : '' ?>"><p class="hint">Stored encrypted. It is never shown again.</p></div>
        <div class="field"><label for="gws">Webhook signing secret <?= isset($api['secrets_set']['webhook_secret']) ? '<span class="badge badge-active">saved ' . e($api['secrets_set']['webhook_secret']) . '</span>' : '' ?></label><input id="gws" name="webhook_secret" type="password" maxlength="200" autocomplete="new-password" placeholder="<?= isset($api['secrets_set']['webhook_secret']) ? 'leave empty to keep the saved secret' : '' ?>"><p class="hint">Used to check that payment notifications really come from the processor. Stored encrypted.</p></div>
        <fieldset class="field"><legend>Card networks to accept</legend><?php foreach ($networks as $c => $l) : ?><label class="check"><input type="checkbox" name="networks[]" value="<?= e($c) ?>"<?= in_array($c, $selNet, true) ? ' checked' : '' ?>> <?= e($l) ?></label><?php endforeach; ?></fieldset>
        <fieldset class="field"><legend>Authentication methods</legend><?php foreach ($authMethods as $c => $l) : ?><label class="check"><input type="checkbox" name="auth_methods[]" value="<?= e($c) ?>"<?= in_array($c, $selAuth, true) ? ' checked' : '' ?>> <?= e($l) ?></label><?php endforeach; ?></fieldset>
        <?php if ($api['secrets_set'] !== []) : ?><div class="field"><label class="check"><input type="checkbox" name="clear_secrets" value="1"> Delete the saved secrets</label></div><?php endif; ?>
        <div class="field"><label for="pw2">Your password</label><input id="pw2" name="confirm_password" type="password" required autocomplete="current-password"></div>
        <div class="form-actions"><button class="btn btn-primary" type="submit">Save Google Pay API fields</button></div></form>
    <?php if ($api['updated_at']) : ?><p class="muted">Last saved <?= e(local_time($api['updated_at'])) ?><?= $api['updated_by'] ? ' by ' . e($api['updated_by']) : '' ?>.</p><?php endif; ?>
    <p class="muted"><strong>Status:</strong> saving these fields does <em>not</em> switch card payments on. The connection to your processor still has to be built and tested against their sandbox before clients are offered it; until then card payments through Google Pay are not available and invoices are paid through section 1 or by bank transfer.</p></div>
